// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo, useEffect } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
// === 1. FONT LOADER (SAFEGUARDED) ===
const useFontLoader = (fonts: string[]) => {
  const stableFonts = useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  useEffect(() => {
    if (typeof document === "undefined") return; // Safety check for SSR/Lambda

    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(`link[href*="${font.replace(/\s+/g, "+")}"]`)
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// === 2. THEMES & UTILS ===
const THEMES = {
  iMessage: {
    receiverColor: "#e5e5ea",
    receiverTextColor: "#000000",
    senderColor: "#007aff",
    senderTextColor: "#ffffff",
    borderRadius: 35,
  },
  WhatsApp: {
    receiverColor: "#ffffff",
    receiverTextColor: "#000000",
    senderColor: "#dcf8c6",
    senderTextColor: "#000000",
    borderRadius: 16,
  },
  Messenger: {
    receiverColor: "#f1f0f0",
    receiverTextColor: "#000000",
    senderColor: "#0084ff",
    senderTextColor: "#ffffff",
    borderRadius: 35,
  },
  Custom: {
    receiverColor: "#f1f0f0",
    receiverTextColor: "#000000",
    senderColor: "#000000",
    senderTextColor: "#ffffff",
    borderRadius: 35,
  },
};

// Stateless component receiving frame to avoid hook mounting issues
const TypingDots: React.FC<{ color: string; frame: number }> = ({ color, frame }) => {
  return (
    <div style={{ display: "flex", gap: 8, alignItems: "center", height: 20 }}>
      {[0, 1, 2].map((i) => {
        const opacity = interpolate(
          Math.sin(frame / 5 + i * 1.5),
          [-1, 1],
          [0.3, 1],
          {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          }
        );
        return (
          <div
            key={i}
            style={{
              width: 10,
              height: 10,
              borderRadius: "50%",
              backgroundColor: color,
              opacity,
            }}
          />
        );
      })}
    </div>
  );
};

// === 3. SCHEMA ===


export type ChatSequenceProps = Record<string, any>;

// === 4. COMPONENT ===
const ChatSequence: React.FC<ChatSequenceProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  theme = "iMessage",
  customSenderColor = "#0084ff",
  customReceiverColor = "#f1f0f0",
  durationInSeconds = 15,
  messages = [
    { text: "I need to make a promotional video but I'm short on time.", isSender: false },
    { text: "Have you tried Malloy Studio? It turns text into motion graphics.", isSender: true },
    { text: "Wait, so it generates actual animations?", isSender: false },
    { text: "Exactly. It creates smooth, professional motion instantly.", isSender: true },
    { text: "Can I customize the branding and colors?", isSender: false },
    { text: "Yes, you have complete control to tweak every detail.", isSender: true },
    { text: "That sounds like a game changer.", isSender: false },
    { text: "It is. Just type your idea and watch it render.", isSender: true },
  ],
}) => {
  
  useFontLoader(["Inter", "Roboto"]);
  
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Filter empty messages
  const activeMessages = useMemo(() => {
    return messages.filter((m) => m && m.text && m.text.length > 0);
  }, [messages]);

  // Dynamic timing to fit all messages within durationInSeconds
  const totalDurationFrames = durationInSeconds * fps;
  const msgCount = Math.max(1, activeMessages.length);
  const cycleDurationFrames = totalDurationFrames / msgCount;

  // Allocate 60% of cycle to typing, 40% to reading/gap
  const typingDurationFrames = cycleDurationFrames * 0.6;
  const messageGapFrames = cycleDurationFrames * 0.4;

  // Resolve Colors
  const activeTheme = useMemo(() => {
    const base = THEMES[theme] || THEMES["iMessage"]; // Fallback safety
    if (theme === "Custom") {
      return {
        ...base,
        senderColor: customSenderColor,
        receiverColor: customReceiverColor,
      };
    }
    return base;
  }, [theme, customSenderColor, customReceiverColor]);

  // Background Processing
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter, Roboto, sans-serif",
        padding: "60px",
        justifyContent: "flex-end",
        alignItems: "center",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          width: "100%",
          maxWidth: width > 1200 ? 900 : "90%",
          gap: 24,
        }}
      >
        {activeMessages.map((msg, index) => {
          // Calculate Timing for this specific message
          const startTime = index * (typingDurationFrames + messageGapFrames);
          const typingEndTime = startTime + typingDurationFrames;
          
          // Phase 1: Typing Indicator
          const showTyping = frame >= startTime && frame < typingEndTime;
          const typingEnter = spring({
            frame: frame - startTime,
            fps,
            config: { damping: 20, stiffness: 200 },
          });

          // Phase 2: Message Reveal
          const showMessage = frame >= typingEndTime;
          const msgEnter = spring({
            frame: frame - typingEndTime,
            fps,
            config: { damping: 15, stiffness: 120 },
          });

          const isSender = msg.isSender;
          const bubbleColor = isSender ? activeTheme.senderColor : activeTheme.receiverColor;
          const textColor = isSender ? activeTheme.senderTextColor : activeTheme.receiverTextColor;
          const alignSelf = isSender ? "flex-end" : "flex-start";

          // Safe scale calculation preventing flip on overshoot
          const typingScale = Math.max(0, typingEnter); 
          const msgScale = Math.max(0, msgEnter);

          return (
            <div
              key={index}
              style={{
                display: "flex",
                flexDirection: "column",
                alignSelf,
                maxWidth: "85%",
              }}
            >
              {/* TYPING BUBBLE */}
              {showTyping && (
                <div
                  style={{
                    backgroundColor: activeTheme.receiverColor,
                    padding: "20px 28px",
                    borderRadius: activeTheme.borderRadius,
                    alignSelf: "flex-start",
                    alignItems: "center",
                    justifyContent: "center",
                    width: "fit-content",
                    transform: `scale(${typingScale})`,
                    transformOrigin: isSender ? "bottom right" : "bottom left",
                  }}
                >
                   <TypingDots color="#888888" frame={frame} />
                </div>
              )}

              {/* ACTUAL MESSAGE BUBBLE */}
              {showMessage && (
                <div
                  style={{
                    backgroundColor: bubbleColor,
                    color: textColor,
                    padding: "20px 28px",
                    borderRadius: activeTheme.borderRadius,
                    borderBottomRightRadius: isSender ? 8 : activeTheme.borderRadius,
                    borderBottomLeftRadius: !isSender ? 8 : activeTheme.borderRadius,
                    fontSize: 32,
                    lineHeight: 1.4,
                    boxShadow: "0 4px 8px rgba(0,0,0,0.05)",
                    transform: `scale(${msgScale})`,
                    opacity: interpolate(msgEnter, [0, 1], [0, 1], {
                      extrapolateLeft: "clamp",
                      extrapolateRight: "clamp",
                    }),
                    transformOrigin: isSender ? "bottom right" : "bottom left",
                  }}
                >
                  {msg.text}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default ChatSequence;